import { Page, Locator } from '@playwright/test';

export class ShoppingCartPage {
    private readonly page: Page;

    // Locators
    private readonly headingCart: Locator;
    private readonly rowsCartItems: Locator;
    private readonly lblCartTotal: Locator;

    constructor(page: Page) {
        this.page = page;

        // Initialize locators with CSS selectors
        this.headingCart = page.getByRole('heading', { name: /^Shopping Cart/ });
        this.rowsCartItems = page.locator('#content form tbody tr');
        // Matches the "Total:" row only (not "Sub-Total:") in the totals table.
        this.lblCartTotal = page
            .locator('#content table tr')
            .filter({ has: page.locator('strong', { hasText: /^Total:$/ }) })
            .locator('td')
            .last();
    }

    /**
     * Returns the cart row for the given product
     * @param productName - Exact product name
     * @returns Locator - Cart row
     */
    private getProductRow(productName: string): Locator {
        return this.rowsCartItems.filter({
            has: this.page.getByRole('link', { name: productName, exact: true }),
        });
    }

    /**
     * Verifies the shopping cart page is displayed
     * @returns Promise<boolean> - true if the "Shopping Cart" heading is displayed
     */
    async isShoppingCartPageExists(): Promise<boolean> {
        try {
            await this.headingCart.waitFor({ state: 'visible' });
            return true;
        } catch (error) {
            console.log(`Error checking shopping cart page: ${error}`);
            return false;
        }
    }

    /**
     * Checks whether the given product is in the cart
     * @param productName - Exact product name
     * @returns Promise<boolean> - true if the product is in the cart
     */
    async isProductInCart(productName: string): Promise<boolean> {
        try {
            await this.getProductRow(productName).first().waitFor({ state: 'visible' });
            return true;
        } catch (error) {
            console.log(`Error checking product in cart: ${error}`);
            return false;
        }
    }

    /**
     * Gets the quantity of the given product in the cart
     * @param productName - Exact product name
     * @returns Promise<string> - Quantity value
     */
    async getProductQuantity(productName: string): Promise<string> {
        return await this.getProductRow(productName).locator('input[name^="quantity"]').inputValue();
    }

    /**
     * Gets the unit price of the given product in the cart
     * @param productName - Exact product name
     * @returns Promise<string> - Unit price text, e.g. "$602.00"
     */
    async getUnitPrice(productName: string): Promise<string> {
        // Columns: Image, Product Name, Model, Quantity, Unit Price, Total
        return (await this.getProductRow(productName).locator('td').nth(4).textContent())?.trim() ?? '';
    }

    /**
     * Gets the line total of the given product in the cart
     * @param productName - Exact product name
     * @returns Promise<string> - Line total text, e.g. "$1,204.00"
     */
    async getProductTotal(productName: string): Promise<string> {
        return (await this.getProductRow(productName).locator('td').nth(5).textContent())?.trim() ?? '';
    }

    /**
     * Gets the cart grand total
     * @returns Promise<string> - Cart total text, e.g. "$602.00"
     */
    async getCartTotal(): Promise<string> {
        return (await this.lblCartTotal.textContent())?.trim() ?? '';
    }
}
